import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import "../../style/blog.css";

const BlogDetailsPage = () => {
  const { id } = useParams();
  const [blog, setBlog] = useState(null);

  useEffect(() => {
    // Normally fetch from backend, for now using static data
    const allBlogs = [
      {
        id: 1,
        title: "Top 10 Gadgets You Need in 2025",
        date: "August 15, 2025",
        image: "/blog1.jpeg"
,
        content: `
          In 2025, technology continues to evolve at lightning speed. 
          Here are the top 10 gadgets you need to upgrade your daily life.
          1. AI-powered assistants
          2. Foldable smartphones
          3. Smart home security systems
          ...
        `
      },
      {
        id: 2,
        title: "How to Choose the Right Laptop",
        date: "August 10, 2025",
        image: "/images/blog2.jpg",
        content: `
          Choosing the right laptop can be tricky. 
          We break down everything from performance specs to battery life 
          to help you make the right decision.
        `
      },
      
    ];

    const foundBlog = allBlogs.find((b) => b.id === parseInt(id));
    setBlog(foundBlog);
  }, [id]);

  if (!blog) {
    return <p style={{ padding: "20px" }}>Loading blog...</p>;
  }

  return (
    <div className="blog-details">
      <img src={blog.image} alt={blog.title} />
      <h1>{blog.title}</h1>
      <p className="date">{blog.date}</p>
      <p className="content">{blog.content}</p>
      <Link to="/blog" className="back-link">← Back to Blog</Link>
    </div>
  );
};

export default BlogDetailsPage;
